// The one PayPal call Settle makes through PayPal's TypeScript SDK, generated by APIMatic
// (package `paypal`, built from github.com/context-plugins/paypal-typescript-sdk, pinned in
// package.json): add tracking to a captured order, as the connected seller. Everything else stays
// on plain fetch in lib/paypal.ts (DECISIONS #2, amended Nov 4). Server-only.
//
// Contract facts come from the SDK map (node_modules/paypal/map/operations/orders.md,
// createOrderTracking): path `id`, header `payPalAuthAssertion`, body `OrderTrackerRequest`
// with `captureId` required. The SDK mints its own Idempotency-Key per call, which does not span
// calls, so lib/settle/shipping.ts claims the write on the deal record first.

import { PaypalClient, PaypalError, type Orders, type ShipmentCarrier } from 'paypal';
import { authAssertion, BASE_URL } from './paypal';

let shared: PaypalClient | undefined;

/** One client for the process: its OAuth token cache lives on it. */
export function sdkClient(): PaypalClient {
  if (shared) return shared;
  const { PAYPAL_CLIENT_ID: clientId, PAYPAL_SECRET: clientSecret } = process.env;
  // An unset credential is not an SDK error (it would just 401 later), so check here.
  if (!clientId || !clientSecret) throw new Error('PAYPAL_CLIENT_ID and PAYPAL_SECRET must be set (see .env.local)');
  shared = new PaypalClient({
    oauth2: { clientId, clientSecret },
    // Sandbox only (CLAUDE.md): the same host as lib/paypal.ts, stated rather than inherited.
    serverOptions: { baseUrl: BASE_URL },
    // Per attempt. POST is not retried by default, and stays that way.
    retry: { timeout: 15_000 },
    // Off, and set in code so PAYPAL_CLIENT_LOG can't switch it on.
    logging: { level: 'off' },
  });
  return shared;
}

export type TrackingInput = {
  orderId: string;
  captureId: string;
  sellerMerchantId: string;
  trackingNumber: string;
  carrier: ShipmentCarrier;
  /** Only when carrier is OTHER. */
  carrierNameOther?: string;
};

export type TrackingOutcome =
  | { ok: true; debugId?: string }
  /** PayPal answered with an error status: nothing was added. */
  | { ok: false; refused: true; status: number; reason?: string; debugId?: string }
  /** No usable answer (connection, timeout, unreadable 2xx): PayPal may have added it. */
  | { ok: false; refused: false; unknown: true; kind: string }
  /** Never sent (credentials not obtained, or a value that would not encode). */
  | { ok: false; refused: false; unknown: false; kind: string };

export async function addTrackingViaSdk(t: TrackingInput, client: PaypalClient = sdkClient()): Promise<TrackingOutcome> {
  const request: Orders.CreateOrderTrackingRequest = {
    id: t.orderId,
    payPalAuthAssertion: authAssertion(t.sellerMerchantId),
    body: {
      captureId: t.captureId,
      trackingNumber: t.trackingNumber,
      carrier: t.carrier,
      ...(t.carrier === 'OTHER' && t.carrierNameOther ? { carrierNameOther: t.carrierNameOther } : {}),
    },
  };
  try {
    // asApiResult: the only way to read paypal-debug-id on a success.
    const outcome = await client.orders.createOrderTracking(request).asApiResult();
    if (outcome.ok) return { ok: true, debugId: outcome.headers.get('paypal-debug-id') ?? undefined };
    const p = outcome.payload;
    const body = p.kind === 'undeclared' ? undefined : p.body;
    const detail = body?.details?.[0];
    const reason = body ? [body.message, detail && (detail as { description?: string }).description].filter(Boolean).join(': ') : undefined;
    return { ok: false, refused: true, status: outcome.status, reason, debugId: body?.debugId ?? outcome.headers.get('paypal-debug-id') ?? undefined };
  } catch (error) {
    if (error instanceof PaypalError) {
      if (error.kind === 'connection' || error.kind === 'timeout') return { ok: false, refused: false, unknown: true, kind: error.kind };
      // PayPal answered, but the body didn't decode: on a 2xx the tracker may exist.
      if (error.kind === 'decode') {
        return error.status >= 200 && error.status < 300
          ? { ok: false, refused: false, unknown: true, kind: 'decode' }
          : { ok: false, refused: true, status: error.status };
      }
      return { ok: false, refused: false, unknown: false, kind: error.kind };
    }
    throw error;
  }
}
